using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Security.Cryptography;using System.Text;using Microsoft.IdentityModel.Tokens;using Npgsql;
namespace IcpaaS.Api;
public sealed record LoginRequest(string Email,string Password,string? Workspace);public sealed record BootstrapRequest(string Email,string Password,string DisplayName,string? TenantSlug,string? TenantName);public sealed record RefreshRequest(string RefreshToken);public sealed record AdminRecoveryRequest(string Email,string Password);public sealed record SessionTokens(string AccessToken,string RefreshToken,int ExpiresIn,string[] Roles,Guid? TenantId);
public sealed class AuthService(PlatformStore store,IConfiguration config){readonly string _secret=config["ICPaaS:Security:JwtSecret"]??throw new InvalidOperationException("JWT secret is required");public async Task<SessionTokens> Login(LoginRequest input,CancellationToken ct){await using var c=await store.Open(ct);var workspace=(input.Workspace??"").Trim();await using var cmd=new NpgsqlCommand("SELECT u.id,u.tenant_id,u.password_hash,u.password_salt,u.roles,u.status,u.token_version FROM users u LEFT JOIN tenants t ON t.id=u.tenant_id WHERE lower(u.email)=lower($1) AND ($2='' OR lower(t.slug)=lower($2)) ORDER BY u.created_at LIMIT 2",c);cmd.Parameters.AddWithValue(input.Email);cmd.Parameters.AddWithValue(workspace);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new UnauthorizedAccessException("Invalid email, password or workspace ID.");var id=r.GetGuid(0);Guid? tenant=r.IsDBNull(1)?null:r.GetGuid(1);var hash=r.GetString(2);var salt=r.GetString(3);var roles=(string[])r[4];var status=r.GetString(5);var version=r.GetInt32(6);if(workspace.Length==0&&await r.ReadAsync(ct))throw new UnauthorizedAccessException("This email exists in multiple workspaces. Enter the Workspace ID.");if(status!="active"||!CryptographicOperations.FixedTimeEquals(Convert.FromHexString(hash),Convert.FromHexString(PlatformStore.Password(input.Password,salt))))throw new UnauthorizedAccessException("Invalid email, password or workspace ID.");await r.CloseAsync();return await Issue(id,tenant,roles,version,ct);}
public async Task<SessionTokens> Bootstrap(BootstrapRequest input,string supplied,CancellationToken ct){var expected=config["ICPaaS:Security:BootstrapKey"]??"";var expectedBytes=Encoding.UTF8.GetBytes(expected);var suppliedBytes=Encoding.UTF8.GetBytes(supplied);if(expected.Length<24||expectedBytes.Length!=suppliedBytes.Length||!CryptographicOperations.FixedTimeEquals(expectedBytes,suppliedBytes))throw new UnauthorizedAccessException("Invalid bootstrap key");await using var c=await store.Open(ct);await using var tx=await c.BeginTransactionAsync(ct);var count=Convert.ToInt32(await new NpgsqlCommand("SELECT count(*) FROM users",c,tx).ExecuteScalarAsync(ct));if(count>0)throw new InvalidOperationException("Bootstrap is already complete");Guid? tenant=null;if(!string.IsNullOrWhiteSpace(input.TenantSlug)){await using var t=new NpgsqlCommand("INSERT INTO tenants(slug,name) VALUES($1,$2) RETURNING id",c,tx);t.Parameters.AddWithValue(input.TenantSlug);t.Parameters.AddWithValue(input.TenantName??input.TenantSlug);tenant=(Guid)(await t.ExecuteScalarAsync(ct))!;await using var s=new NpgsqlCommand("INSERT INTO tenant_settings(tenant_id) VALUES($1)",c,tx);s.Parameters.AddWithValue(tenant.Value);await s.ExecuteNonQueryAsync(ct);}var salt=PlatformStore.Salt();await using var u=new NpgsqlCommand("INSERT INTO users(tenant_id,email,display_name,password_hash,password_salt,roles) VALUES($1,$2,$3,$4,$5,$6) RETURNING id",c,tx);u.Parameters.AddWithValue((object?)tenant??DBNull.Value);u.Parameters.AddWithValue(input.Email.ToLowerInvariant());u.Parameters.AddWithValue(input.DisplayName);u.Parameters.AddWithValue(PlatformStore.Password(input.Password,salt));u.Parameters.AddWithValue(salt);u.Parameters.AddWithValue(tenant is null?new[]{"platform_admin"}:new[]{"tenant_owner"});var id=(Guid)(await u.ExecuteScalarAsync(ct))!;await tx.CommitAsync(ct);return await Issue(id,tenant,tenant is null?new[]{"platform_admin"}:new[]{"tenant_owner"},1,ct);}
public async Task ResetPlatformAdmin(AdminRecoveryRequest input,string supplied,CancellationToken ct){var expected=config["ICPaaS:Security:BootstrapKey"]??"";var a=Encoding.UTF8.GetBytes(expected);var b=Encoding.UTF8.GetBytes(supplied);if(expected.Length<24||a.Length!=b.Length||!CryptographicOperations.FixedTimeEquals(a,b))throw new UnauthorizedAccessException("Invalid recovery key");if(input.Password.Length<12)throw new ArgumentException("Password must be at least 12 characters");var salt=PlatformStore.Salt();await using var c=await store.Open(ct);await using var cmd=new NpgsqlCommand("UPDATE users SET password_hash=$2,password_salt=$3,token_version=token_version+1,updated_at=now() WHERE tenant_id IS NULL AND lower(email)=lower($1) AND 'platform_admin'=ANY(roles) RETURNING id",c);cmd.Parameters.AddWithValue(input.Email);cmd.Parameters.AddWithValue(PlatformStore.Password(input.Password,salt));cmd.Parameters.AddWithValue(salt);var id=await cmd.ExecuteScalarAsync(ct);if(id is null)throw new InvalidOperationException("Platform administrator not found");await using var revoke=new NpgsqlCommand("UPDATE refresh_tokens SET revoked_at=COALESCE(revoked_at,now()) WHERE user_id=$1",c);revoke.Parameters.AddWithValue((Guid)id);await revoke.ExecuteNonQueryAsync(ct);}
public async Task<SessionTokens> Refresh(RefreshRequest input,CancellationToken ct){await using var c=await store.Open(ct);await using var cmd=new NpgsqlCommand("SELECT u.id,u.tenant_id,u.roles,u.token_version,r.id FROM refresh_tokens r JOIN users u ON u.id=r.user_id WHERE r.token_hash=$1 AND r.revoked_at IS NULL AND r.expires_at>now() AND u.status='active' FOR UPDATE",c);cmd.Parameters.AddWithValue(PlatformStore.Hash(input.RefreshToken));await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new UnauthorizedAccessException("Invalid refresh token");var uid=r.GetGuid(0);Guid? tenant=r.IsDBNull(1)?null:r.GetGuid(1);var roles=(string[])r[2];var version=r.GetInt32(3);var old=r.GetGuid(4);await r.CloseAsync();await using var revoke=new NpgsqlCommand("UPDATE refresh_tokens SET revoked_at=now() WHERE id=$1",c);revoke.Parameters.AddWithValue(old);await revoke.ExecuteNonQueryAsync(ct);return await Issue(uid,tenant,roles,version,ct);}
async Task<SessionTokens> Issue(Guid id,Guid? tenant,string[] roles,int version,CancellationToken ct){var claims=new List<Claim>{new(JwtRegisteredClaimNames.Sub,id.ToString()),new("token_version",version.ToString())};claims.AddRange(roles.Select(x=>new Claim(ClaimTypes.Role,x)));if(tenant.HasValue)claims.Add(new("tenant_id",tenant.Value.ToString()));var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_secret));var expires=DateTime.UtcNow.AddMinutes(15);var jwt=new JwtSecurityToken("icpaas","icpaas-api",claims,expires:expires,signingCredentials:new SigningCredentials(key,SecurityAlgorithms.HmacSha256));var raw=Convert.ToBase64String(RandomNumberGenerator.GetBytes(48));await using var c=await store.Open(ct);await using var cmd=new NpgsqlCommand("INSERT INTO refresh_tokens(user_id,tenant_id,token_hash,expires_at) VALUES($1,$2,$3,now()+interval '30 days')",c);cmd.Parameters.AddWithValue(id);cmd.Parameters.AddWithValue((object?)tenant??DBNull.Value);cmd.Parameters.AddWithValue(PlatformStore.Hash(raw));await cmd.ExecuteNonQueryAsync(ct);return new(new JwtSecurityTokenHandler().WriteToken(jwt),raw,900,roles,tenant);}}
